<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { approveSkill, fetchSkillReviews, rejectSkill, type ReviewItem } from '@/api/skills'
const items=ref<ReviewItem[]>([]),loading=ref(true),busy=ref(''),error=ref(''),notes=ref<Record<string,string>>({})
function msg(e:unknown){return e instanceof Error?e.message:'审核操作失败'}
async function load(){loading.value=true;error.value='';try{items.value=await fetchSkillReviews()}catch(e){error.value=msg(e)}finally{loading.value=false}}
async function act(id:string,work:()=>Promise<unknown>){busy.value=id;error.value='';try{await work();await load()}catch(e){error.value=msg(e)}finally{busy.value=''}}
onMounted(load)
</script>
<template>
  <header class="page-head"><div><h1 class="market-title">Skill 审核队列</h1><p class="market-lead">安全预览仅显示纯文本，不渲染 HTML，不执行脚本。</p></div><button class="market-button" @click="load">刷新</button></header>
  <div v-if="error" class="market-error">{{ error }}</div><div v-if="loading" class="market-card market-empty">正在加载待审核版本…</div><div v-else-if="!items.length" class="market-card market-empty"><h2>队列已清空</h2><p>当前没有待审核 Skill。</p></div>
  <div v-else class="review-list"><article v-for="item in items" :key="item.version.id" class="market-card review"><header><div><span>@{{ item.publisher.handle }}</span><h2>{{ item.skill.displayName }} <small>v{{ item.version.version }}</small></h2><p>{{ item.skill.summary }}</p></div><div><b>{{ item.version.license }}</b><small>{{ item.version.fileCount }} 文件 · {{ Math.ceil(item.version.packageSize/1024) }} KiB</small></div></header><div v-if="item.version.findings.length" class="market-error"><div v-for="finding in item.version.findings" :key="finding">{{ finding }}</div></div><div class="inspection"><section><h3>SKILL.md</h3><pre>{{ item.version.skillMd }}</pre></section><section><h3>文件树</h3><ul><li v-for="file in item.version.files" :key="file.path"><span>{{ file.path }}</span><small>{{ file.size }} B</small></li></ul></section></div><div class="hash">SHA-256 <code>{{ item.version.sha256 }}</code></div><footer><input v-model="notes[item.version.id]" class="market-input" placeholder="驳回时必填具体修改意见"><button class="market-button danger" :disabled="!!busy || !notes[item.version.id]?.trim()" @click="act(item.version.id,()=>rejectSkill(item.version.id,notes[item.version.id] || ''))">驳回</button><button class="market-button primary" :disabled="!!busy || !!item.version.findings.length" @click="act(item.version.id,()=>approveSkill(item.version.id))">通过并发布</button></footer></article></div>
</template>
<style scoped>
.page-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:26px}.review-list{display:grid;gap:18px}.review{padding:24px}.review>header{display:flex;justify-content:space-between;gap:20px}.review h2{margin:7px 0}.review header p,.review header span,.review header small{color:var(--market-sub)}.review header>div:last-child{display:grid;text-align:right;gap:5px}.inspection{display:grid;grid-template-columns:1fr 1fr;gap:14px}.inspection pre,.inspection ul{height:380px;overflow:auto;background:#151a27;color:#e8ebf5;border-radius:12px;padding:16px;font-size:12px;line-height:1.65;white-space:pre-wrap}.inspection ul{list-style:none}.inspection li{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #2a3040;padding:6px}.hash{font-size:12px;overflow-wrap:anywhere;background:#f6f7fa;border-radius:8px;padding:11px}.review footer{display:grid;grid-template-columns:1fr auto auto;gap:9px;margin-top:16px}@media(max-width:720px){.inspection{grid-template-columns:1fr}.review footer{grid-template-columns:1fr}.review>header{flex-direction:column}.review header>div:last-child{text-align:left}}
</style>
